"""Stage B74 acquisition metadata, preserving adopted documents byte-for-byte."""
from pathlib import Path
import argparse,json,hashlib
r=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
items=json.loads((r/'docs/v07/data/items.json').read_text())['items'];acq=json.loads((r/'docs/v07/data/acquisition.json').read_text());abilities=json.loads((r/'docs/v07/data/abilities.json').read_text())['abilities']
known={'null_bell': 'NullBell', 'iron_halberd': 'IronHalberd', 'simple_staff': 'SimpleStaff', 'runic_staff': 'RunicStaff', 'conduit_staff': 'ConduitStaff', 'bastion_plate': 'BastionPlate', 'archivist_robe': 'ArchivistRobe', 'merchant_harness': 'MerchantHarness', 'pathfinder_boots': 'PathfinderBoots', 'scholars_sigil': 'ScholarsSigil', 'warding_eye': 'WardingEye', 'weighted_satchel': 'WeightedSatchel', 'watchblade': 'Watchblade', 'surveyor_bow': 'SurveyorBow', 'oath_mace': 'OathMace', 'null_dagger': 'NullDagger', 'shade_mantle': 'ShadeMantle', 'reflective_mail': 'ReflectiveMail', 'silent_soles': 'SilentSoles', 'cliffwalkers': 'Cliffwalkers', 'anchor_greaves': 'AnchorGreaves', 'brokers_seal': 'BrokersSeal', 'iron_oath': 'IronOath', 'smoke_flask': 'SmokeFlask', 'seers_dust': 'SeersDust', 'healing_salve': 'HealingSalve', 'mana_draught': 'ManaDraught', 'ward_totem': 'WardTotem', 'recall_token': 'RecallToken', 'snare_mine': 'SnareMine', 'counterglyph': 'Counterglyph', 'mirror_sigil': 'MirrorSigil', 'purity_charm': 'PurityCharm', 'aegis_flask': 'AegisFlask', 'grappling_chain': 'GrapplingChain', 'blink_charm': 'BlinkCharm', 'null_staff': 'NullStaff', 'rift_staff': 'RiftStaff', 'harpoon_halberd': 'HarpoonHalberd', 'tower_relic': 'TowerRelic', 'arcane_catalyst': 'ArcaneCatalyst', 'heart_fragment': 'HeartFragment', 'ancient_key_a': 'AncientKeyA', 'ancient_key_b': 'AncientKeyB', 'ancient_key_c': 'AncientKeyC', 'heartbreaker': 'Heartbreaker'}
payload={'schema_version':7,'quality_multipliers':json.loads((r/'docs/v07/data/items.json').read_text())['quality_multipliers'],'items':[{**i,'kind':known[i['id']]} for i in items], 'acquisition':acq,'books':[{'id':a['id'],'skill':10+n,'circle':a['circle']} for n,a in enumerate(abilities)]}
raw=(json.dumps(payload,indent=2)+'\n').encode();header=('#pragma once\n#define LD_ACQUISITION_SHA TEXT("'+hashlib.sha256(raw).hexdigest()+'")\n').encode()
for path,data in [(r/'Content/Lockdown/Data/V07/acquisition.json',raw),(r/'Source/Lockdown/Private/Inventory/LDAcquisitionContract.h',header)]:
 if args.check:assert path.read_bytes().replace(b'\r\n',b'\n')==data,path
 else:path.write_bytes(data)
print('PASS B74 acquisition '+hashlib.sha256(raw).hexdigest())
